const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const KEY='elevor_arvia_v1';const V12KEY='elevor_arvia_v12';const V11KEY='elevor_arvia_v11';const V10KEY='elevor_arvia_v10';const V9KEY='elevor_arvia_v9';const V8KEY='elevor_arvia_v8';const V7KEY='elevor_arvia_v7';const V6KEY='elevor_arvia_v6';const V5KEY='elevor_arvia_v5';const V43KEY='elevor_arvia_v4_3';const V42KEY='elevor_arvia_v4_2';const PREVKEY='elevor_arvia_v4_1';const V4KEY='elevor_arvia_v4';const V3KEY='elevor_arvia_v3';const OLDKEY='elevor_arvia_v2';const LEGACYKEY='elevor_arvia_v1';let data={cabin:'',deck:'',muster:'',notes:'',departure:'',days:7,ports:'',plans:[],drinks:[],spend:[],favorites:[],limit:15,passengers:['Passenger 1'],activePassenger:'Passenger 1',deckNotes:{},venueNotes:{},cabinRoute:'',venueFilter:'All',venueDecks:{},customVenues:[],cabinDirectory:[]};try{data={...data,...JSON.parse(localStorage.getItem(KEY)||localStorage.getItem(V12KEY)||localStorage.getItem(V11KEY)||localStorage.getItem(V10KEY)||localStorage.getItem(V9KEY)||localStorage.getItem(V8KEY)||localStorage.getItem(V7KEY)||localStorage.getItem(V6KEY)||localStorage.getItem(V5KEY)||localStorage.getItem(V43KEY)||localStorage.getItem(V42KEY)||localStorage.getItem(PREVKEY)||localStorage.getItem(V4KEY)||localStorage.getItem(V3KEY)||localStorage.getItem(OLDKEY)||localStorage.getItem(LEGACYKEY)||'{}')}}catch{}if(!Array.isArray(data.passengers)||!data.passengers.length)data.passengers=['Passenger 1'];if(!data.passengers.includes(data.activePassenger))data.activePassenger=data.passengers[0];let venues=[],ads={enabled:false},information={title:'Passenger information',updated:'',sections:[]};let page='home';let updateStatus='';const save=()=>localStorage.setItem(KEY,JSON.stringify(data));const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};const money=n=>'£'+Number(n||0).toFixed(2);const pages=[['home','🏠 Home'],['myday','☀️ My Day'],['ship','🛳 Ship & Cabin'],['decks','🧭 Deck Guide'],['cabins','🔎 Cabin Finder'],['favorites','⭐ Favourites'],['venues','🍽 Bars & Dining'],['facilities','🛗 Facilities'],['entertainment','🎭 Entertainment'],['drinks','🍹 Drinks'],['planner','📅 My Cruise'],['packing','🧳 Packing List'],['information','ℹ️ Information'],['spend','💷 Spending'],['share','📲 Share App'],['settings','⚙️ Settings']];const PACKING_DEFAULTS=[['Documents','Passport / travel ID'],['Documents','Cruise booking details'],['Documents','Travel insurance details'],['Documents','Required travel documents'],['Clothing','Daytime outfits'],['Clothing','Evening outfits'],['Clothing','Comfortable shoes'],['Clothing','Swimwear'],['Health','Personal medication'],['Health','Sun protection'],['Electronics','Phone charger'],['Electronics','Travel adapter (check ship rules)'],['Other','Toiletries'],['Other','Luggage tags']];
if(!Array.isArray(data.packing))data.packing=PACKING_DEFAULTS.map(([category,name],i)=>({id:'default-'+i,category,name,done:false}));
function packingPage(){let items=data.packing,done=items.filter(x=>x.done).length;let cats=[...new Set(items.map(x=>x.category))];return `<section class="card"><h2>Holiday packing checklist</h2><p class="muted">Tick items as you pack. Your list is saved offline on this device. Check your booking documents for current requirements and prohibited items.</p><div class="num">${done} / ${items.length}</div><p>${items.length?Math.round(done/items.length*100):100}% packed</p><div class="meter"><div style="width:${items.length?done/items.length*100:100}%"></div></div><div class="actions"><button class="secondary" id="resetPacking">Untick all</button><button class="secondary" id="exportPacking">Print / Save checklist PDF</button></div></section><section class="card"><h2>Add packing item</h2>${field('Item','packingName')}<label for="packingCategory">Category</label><select id="packingCategory">${['Documents','Clothing','Health','Electronics','Other'].map(x=>`<option>${x}</option>`).join('')}</select><button id="addPacking">Add item</button></section>${cats.map(cat=>`<section class="card"><h2>${esc(cat)}</h2>${items.filter(x=>x.category===cat).map(x=>`<div class="item row"><label style="display:flex;align-items:center;gap:10px;flex:1"><input type="checkbox" data-pack-check="${esc(x.id)}" ${x.done?'checked':''} style="width:auto"><span style="${x.done?'text-decoration:line-through;opacity:.65':''}">${esc(x.name)}</span></label><button class="danger" data-pack-remove="${esc(x.id)}" aria-label="Remove ${esc(x.name)}">×</button></div>`).join('')}</section>`).join('')}`}
function field(label,id,val='',type='text'){return `<label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(val)}">`}function mediaPath(value){const path=String(value||'').trim();if(!path)return '';if(/^https:\/\//i.test(path))return path;if(/^(?:[a-z]+:|\/\/|\/|\.\.)/i.test(path))return '';return './'+path.replace(/^\.\//,'').split('/').map(encodeURIComponent).join('/')}function ad(slot){if(!ads.enabled||!ads.placements?.includes(slot))return '';let media=mediaPath(ads.image)?`<img src="${esc(mediaPath(ads.image))}" alt="Advertisement">`:mediaPath(ads.video)?`<video controls playsinline style="max-width:100%" src="${esc(mediaPath(ads.video))}"></video>`:'';if(!media)return '';return `<section class="card ad"><small>Advertisement</small><p>${esc(ads.caption||'')}</p>${ads.link?`<a href="${esc(ads.link)}" target="_blank" rel="noopener noreferrer">${media}</a>`:media}</section>`}const DECKS=[4,5,6,7,8,9,10,11,12,14,15,16,17,18,19];const CABIN_TYPES=[['Inside','Confirm cabin category and deck against your booking'],['Sea view','Confirm cabin category and deck against your booking'],['Balcony','Confirm cabin category and deck against your booking'],['Suite','Confirm cabin category and deck against your booking']];function shipDiagram(){return `<div class="ship-layout" role="img" aria-label="Schematic of ship sections, not a scaled cabin plan"><div class="ship-bow">BOW</div><div class="ship-zones">${['Forward','Mid forward','Midship','Mid aft','Aft'].map((x,i)=>`<div class="ship-zone"><strong>${x}</strong><small>${i===0?'Front of ship':i===4?'Rear of ship':'Ship section'}</small></div>`).join('')}</div><p class="muted">Orientation guide only — not a numbered cabin floor plan. Actual cabins, corridors and lift locations must be verified onboard.</p></div>`}function cabinGuide(){return `<section class="card"><h2>Cabin & deck guide</h2><p>Find your way around without leaving this app. Select your deck and save the section of the ship where your cabin is located.</p>${shipDiagram()}<label for="cabinZone">My cabin section</label><select id="cabinZone">${['Not yet confirmed','Forward','Mid forward','Midship','Mid aft','Aft'].map(x=>`<option ${data.cabinZone===x?'selected':''}>${x}</option>`).join('')}</select><button id="saveCabinZone">Save cabin section</button><h3>Cabin types on Arvia</h3><div class="cabin-types">${CABIN_TYPES.map(([name,desc])=>`<div class="item"><b>${name}</b><p>${desc}</p></div>`).join('')}</div><p class="muted">Cabin categories and locations vary. This guide is a simplified reference, not a complete numbered deck plan.</p></section>`}

// A clearly labelled orientation diagram, not a licensed or exact cabin floorplan.
function visualDeck(d){
 const records=(data.cabinDirectory||[]).filter(x=>String(x.deck)===String(d));
 const sections=['Forward','Mid forward','Midship','Mid aft','Aft'];
 const safeZone=x=>sections.includes(x)?x:'Unknown';
 const groups=sections.map(zone=>({zone,rooms:records.filter(x=>safeZone(x.zone)===zone)}));
 const unknown=records.filter(x=>safeZone(x.zone)==='Unknown');
 return `<section class="visual-guide"><h3>Deck ${esc(d)} · ship orientation</h3><p class="muted">Bow at left, stern at right. This is a schematic, NOT a scaled floor plan. Lift and stair positions are not plotted until verified.</p><div class="orientation-strip"><span>◀ BOW / FORWARD</span><span>AFT / STERN ▶</span></div><div class="zone-strip">${groups.map(g=>`<div class="zone-tile"><strong>${esc(g.zone)}</strong><small>${g.rooms.length} saved cabin(s)</small>${g.rooms.slice(0,8).map(r=>`<span class="cabin-chip">${esc(r.cabin)}</span>`).join('')}${g.rooms.length>8?`<small>+${g.rooms.length-8} more</small>`:''}</div>`).join('')}</div>${unknown.length?`<p>${unknown.length} saved cabin(s) have no confirmed section.</p>`:''}<p class="muted">Saved cabin positions come from your own records. They are not independently verified by this app.</p><div class="guide-key"><span>🛗 Lifts: use your personal deck notes</span><span>↕ Stairs: check onboard signs</span></div></section>`;
}
function cabinFinder(){let records=Array.isArray(data.cabinDirectory)?data.cabinDirectory:[];return `<section class="card"><h2>Cabin number finder</h2><p class="muted">Search your saved cabin records by number, deck or location. This is a passenger-maintained directory, not an official numbered floor plan. No unverified cabin positions are supplied.</p><label for="cabinSearch">Search cabin number or deck</label><input id="cabinSearch" placeholder="e.g. 10123 or deck 10"><div id="cabinResults"></div></section><section class="card"><h2>Add a verified cabin location</h2><p class="muted">Enter cabin details from your booking paperwork or a deck plan you have checked. Records are saved on this device only.</p>${field('Cabin number','entryCabin')}${field('Deck','entryDeck','','number')}<label for="entryZone">Ship section</label><select id="entryZone">${['Unknown','Forward','Mid forward','Midship','Mid aft','Aft'].map(x=>`<option>${x}</option>`).join('')}</select><label for="entrySide">Side (if known)</label><select id="entrySide"><option>Unknown</option><option>Port</option><option>Starboard</option></select>${field('Cabin type (optional)','entryType')}${field('Directions / nearby lift (optional)','entryNotes')}<div class="actions"><button id="addCabinEntry">Save cabin location</button></div></section><section class="card"><h2>Cabin directory management</h2><p>${records.length} saved cabin location(s). You can import a verified CSV of cabin records without publishing external links.</p><div class="actions"><button id="exportCabins">Print / Save cabin list PDF</button><label style="margin:0"><span class="tag">Import cabin CSV</span><input id="importCabins" type="file" accept=".csv,text/csv"></label></div><p class="muted">CSV columns: cabin,deck,zone,side,type,notes. Import replaces matching cabin numbers and keeps other entries. Please only import data you have permission to use.</p></section>`}
function cabinRows(q=''){let records=Array.isArray(data.cabinDirectory)?data.cabinDirectory:[];let search=q.trim().toLowerCase().replace(/^deck\s+/, '');let rows=records.filter(x=>!search||[x.cabin,x.deck,x.zone,x.side,x.type,x.notes].some(v=>String(v||'').toLowerCase().includes(search))).sort((a,b)=>String(a.cabin).localeCompare(String(b.cabin),undefined,{numeric:true}));return rows.length?rows.map(x=>`<div class="item row"><span><b>Cabin ${esc(x.cabin)}</b> · Deck ${esc(x.deck)}<br><small>${esc(x.zone)} · ${esc(x.side)} · ${esc(x.type||'Type not recorded')}</small>${x.notes?`<p>${esc(x.notes)}</p>`:''}</span><button class="danger" data-remove-cabin="${esc(x.cabin)}">Delete</button></div>`).join(''):'No matching cabin records saved yet.'}
function parseCSV(text){let out=[],row=[],value='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){value+='"';i++}else if(c==='"')quoted=false;else value+=c}else if(c==='"')quoted=true;else if(c===','){row.push(value);value=''}else if(c==='\n'){row.push(value.replace(/\r$/,''));out.push(row);row=[];value=''}else value+=c}if(value||row.length){row.push(value);out.push(row)}return out}
function cabinCSV(){let cols=['cabin','deck','zone','side','type','notes'];let quote=x=>'"'+String(x??'').replace(/"/g,'""')+'"';return [cols.join(','),...(data.cabinDirectory||[]).map(x=>cols.map(c=>quote(x[c])).join(','))].join('\r\n')}

function printReport(title,headers,rows,note=''){
 const win=window.open('','_blank');
 if(!win){alert('Please allow pop-ups for this app to print or save a PDF.');return}
 const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const body=rows.length?rows.map(row=>'<tr>'+row.map(cell=>'<td>'+e(cell)+'</td>').join('')+'</tr>').join(''):`<tr><td colspan="${headers.length}">No records saved yet.</td></tr>`;
 win.document.open();
 win.document.write(`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(title)}</title><style>
 @page{size:A4;margin:15mm}body{font:12px Arial,sans-serif;color:#14273b;margin:20px}h1{font-size:22px;margin-bottom:5px}p{color:#475569}table{width:100%;border-collapse:collapse;table-layout:auto}th,td{border:1px solid #cbd5e1;padding:7px;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#eaf0f5}tr{break-inside:avoid}thead{display:table-header-group}.toolbar{margin:14px 0 24px}.toolbar button{padding:10px 16px;font-size:14px}@media print{.toolbar{display:none}body{margin:0}}
 </style></head><body><h1>${e(title)}</h1><p>Elevor360D Arvia Cruise Companion · ${e(new Date().toLocaleDateString('en-GB'))}</p>${note?`<p>${e(note)}</p>`:''}<div class="toolbar"><button onclick="window.print()">Print / Save as PDF</button> <button onclick="window.close()">Close</button><p>In the print dialog choose “Save as PDF” or your printer.</p></div><table><thead><tr>${headers.map(h=>'<th>'+e(h)+'</th>').join('')}</tr></thead><tbody>${body}</tbody></table></body></html>`);
 win.document.close();
 win.focus();
}

function downloadText(filename,contents,mime){let blob=new Blob([contents],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

const FACILITIES=[
{name:'Medical Centre',deck:'3–4',category:'Medical',notes:'Published deck plans label the medical centre on the lower decks; confirm access onboard.'},
{name:'Oasis Spa & Thermal Suite',deck:'6',category:'Wellness',notes:'Spa and treatment facilities.'},
{name:'Gym',deck:'6',category:'Wellness',notes:'Fitness facilities.'},
{name:'The Reef',deck:'17',category:'Family',notes:'Children’s club facilities; check age-group arrangements onboard.'},
{name:'SkyDome',deck:'16–17',category:'Leisure',notes:'Pool and entertainment area spanning levels.'},
{name:'Infinity Pool',deck:'16',category:'Leisure',notes:'Outdoor pool area.'},
{name:'Lifts and stairs',deck:'Various',category:'Navigation',notes:'Multiple lift and stair banks. Exact bank and accessible routes are not mapped in this guide.'},
{name:'Public toilets',deck:'Various',category:'Facilities',notes:'Exact positions not independently verified. Follow onboard signs.'},
{name:'Laundry',deck:'Cabin decks',category:'Facilities',notes:'Consult onboard signs for the nearest guest laundry.'}
];
function facilityGuide(){return `<section class="card"><h2>Facilities finder</h2><p class="muted">Searchable offline reference. Locations labelled “Various” or a range are not exact directions.</p><input id="facilitySearch" placeholder="Search pool, gym, lifts, toilets..." aria-label="Search facilities"><label for="facilityCategory">Category</label><select id="facilityCategory"><option>All</option>${[...new Set(FACILITIES.map(x=>x.category))].map(x=>`<option>${esc(x)}</option>`).join('')}</select><div id="facilityResults"></div><p class="muted">Accessibility routes and emergency directions must be confirmed with ship staff and onboard signage.</p></section>`}
function facilityRows(){let q=($('#facilitySearch')?.value||'').toLowerCase(),c=$('#facilityCategory')?.value||'All';$('#facilityResults').innerHTML=FACILITIES.filter(x=>(c==='All'||x.category===c)&&(x.name+' '+x.deck+' '+x.notes).toLowerCase().includes(q)).map(x=>`<div class="item"><b>${esc(x.name)}</b> <span class="tag">${esc(x.category)}</span><p>Deck: ${esc(x.deck)}</p><small>${esc(x.notes)}</small></div>`).join('')||'<p>No matching facilities.</p>'}

function venueDeck(v){return data.venueDecks?.[v.name]||v.deck||'Not confirmed'}function deckVenueRows(d){return venueRows(venues.filter(v=>String(venueDeck(v))===String(d)))}function drinkPeriod(d){let x=new Date(d);if(x.getHours()<6)x.setDate(x.getDate()-1);return [x.getFullYear(),String(x.getMonth()+1).padStart(2,'0'),String(x.getDate()).padStart(2,'0')].join('-')}function periodForDrink(x){if(x.period)return x.period;return x.date||''}function cruiseSummary(){if(!data.departure)return '<p class="muted">Set your embarkation date in My Cruise to see a countdown and upcoming activity.</p>';const start=new Date(data.departure+'T12:00:00');if(Number.isNaN(start.getTime()))return '';const now=new Date(),todayLocal=new Date(now.getFullYear(),now.getMonth(),now.getDate(),12);const daysUntil=Math.round((start-todayLocal)/86400000);const length=Math.max(1,Number(data.days)||1);let status=daysUntil>0?`${daysUntil} day${daysUntil===1?'':'s'} until embarkation`:daysUntil<=-(length)?'Cruise dates have passed':`Cruise day ${1-daysUntil} of ${length}`;const upcoming=(data.plans||[]).filter(x=>x.date&&x.time&&new Date(x.date+'T'+x.time).getTime()>=Date.now()).sort((a,b)=>(a.date+' '+a.time).localeCompare(b.date+' '+b.time))[0];return `<div class="item"><b>${esc(status)}</b>${upcoming?`<p>Next planned activity: ${esc(upcoming.name)} · ${esc(upcoming.date)} at ${esc(upcoming.time)}</p>`:'<p class="muted">No upcoming activities recorded.</p>'}</div>`}function plansCSV(){const q=x=>'"'+String(x??'').replace(/"/g,'""')+'"';return [['Activity','Date','Time'],...(data.plans||[]).slice().sort((a,b)=>(a.date+' '+a.time).localeCompare(b.date+' '+b.time)).map(x=>[x.name,x.date,x.time])].map(r=>r.map(q).join(',')).join('\r\n')}function nav(){ $('#nav').innerHTML=pages.map(([k,n])=>`<button class="${page===k?'active':''}" data-page="${k}">${n}</button>`).join('');document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()})}function render(){nav();let h='';if(page==='home'){h=`<section class="card"><h2>Welcome aboard Arvia</h2><p>Your personal, offline-friendly holiday organiser. Venue locations are an offline reference, not live ship data.</p>${cruiseSummary()}<p><b>My muster point:</b> ${esc(data.muster||'Not set')} · <b>Favourite venues:</b> ${data.favorites.length}</p><div class="grid"><div><b>Cabin</b><p>${esc(data.cabin||'Not set')}</p></div><div><b>Departure</b><p>${esc(data.departure||'Not set')}</p></div><div><b>Recorded drinks today</b><p>${data.drinks.filter(x=>periodForDrink(x)===drinkPeriod(new Date())&&(x.passenger||'Passenger 1')===data.activePassenger&&x.kind==='alcohol').reduce((s,x)=>s+Number(x.qty||0),0)}</p></div><div><b>Packing progress</b><p>${data.packing.filter(x=>x.done).length} of ${data.packing.length} items packed</p></div></div></section>${ad('home')}`}
if(page==='myday'){
 const chosen=data.myDayDate||today();
 const activities=(data.plans||[]).filter(x=>x.date===chosen).slice().sort((a,b)=>(a.time||'').localeCompare(b.time||''));
 const calls=(data.portCalls||[]).filter(x=>x.date===chosen);
 const entries=activities.map(x=>`<div class="item"><b>${esc(x.time||'Time not set')}</b> — ${esc(x.name)}</div>`).join('')||'<p class="muted">No activities planned for this date. Add them in My Cruise.</p>';
 const ports=calls.map(x=>`<div class="item"><b>${esc(x.name)}</b><p>Excursion meeting: ${esc(x.meet||'Not entered')} · Personal return reminder: ${esc(x.returnTime||'Not entered')}</p>${x.notes?`<p>${esc(x.notes)}</p>`:''}</div>`).join('')||'<p class="muted">No port day saved for this date.</p>';
 h=`<section class="card"><h2>My Day — quick overview</h2><p class="muted">Your saved activities and port details in one place. These are personal entries, not live ship schedules or alerts.</p><label for="myDayDate">Choose a date</label><input type="date" id="myDayDate" value="${esc(chosen)}"><div class="actions"><button id="myDayToday" class="secondary">Today</button><button id="myDayPlanner">Open My Cruise planner</button><button id="printMyDay" class="secondary">Print / Save My Day</button></div></section><section class="card"><h2>Today's activities</h2>${entries}</section><section class="card"><h2>Port day details</h2>${ports}<p class="muted">Check official onboard information for the correct all-aboard time.</p></section><section class="card"><h2>My cabin quick reference</h2><p><b>Cabin:</b> ${esc(data.cabin||'Not saved')} · <b>Deck:</b> ${esc(data.deck||'Not saved')}</p><p><b>Muster station:</b> ${esc(data.muster||'Not saved')}</p>${data.cabinRoute?`<p><b>Route:</b> ${esc(data.cabinRoute)}</p>`:''}<button id="myDayCabin" class="secondary">Open cabin details</button></section>`;
}
if(page==='information'){
const sections=information.sections;h=`<section class="card"><h2>${esc(information.title||'Passenger information')}</h2><p class="muted">Updates supplied by the independent guide publisher. Check official onboard notices for time-sensitive information.</p><div class="actions"><button id="refreshInfo" type="button">Check for information updates</button></div><p id="updateStatus" class="muted">${esc(updateStatus||localStorage.getItem('arvia_information_last_check')||'')}</p>${information.updated?`<p class="muted">Publisher update: ${esc(information.updated)}</p>`:''}${sections.length?`<label for="infoSearch">Find information</label><input id="infoSearch" type="search" placeholder="Search headings or information text" aria-label="Search passenger information"><p id="infoCount" class="muted"></p>`:''}</section><div id="infoSections">${sections.length?sections.map(item=>`<section class="card info-section" data-search="${esc(((item.heading||'')+' '+(item.body||'')).toLowerCase())}"><h2>${esc(item.heading||'Information')}</h2><div class="info-body">${esc(item.body||'').replace(/https:\/\/[^\s<]+/g, url => '<a href="'+url+'" target="_blank" rel="noopener noreferrer">'+url+'</a>').replace(/\n/g,'<br>')}</div></section>`).join(''):'<section class="card"><p>No information updates published yet. Connect to the internet to check for updates.</p></section>'}</div>`}

if(page==='favorites'){let selected=venues.filter(v=>data.favorites.includes(v.name));h=`<section class="card"><h2>My favourite venues</h2><p class="muted">Quick access to saved bars, restaurants and entertainment venues.</p>${venueRows(selected)}</section>`}
if(page==='ship'){h=`<section class="card"><h2>My cabin</h2>${field('Cabin number','cabin',data.cabin)}${field('Deck number','deck',data.deck,'number')}${field('Muster station / assembly point','muster',data.muster)}<label for="cabinRoute">My route back to cabin (e.g. lift bank and landmarks)</label><textarea id="cabinRoute">${esc(data.cabinRoute||'')}</textarea><label for="notes">Cabin directions and notes</label><textarea id="notes">${esc(data.notes)}</textarea><div class="actions"><button id="saveCabin">Save cabin</button></div></section>${cabinGuide()}`}
if(page==='cabins'){h=cabinFinder()}
if(page==='facilities'){h=facilityGuide()}
if(page==='decks'){h=`<section class="card"><h2>Interactive deck guide</h2><p class="muted">Choose a deck to see your saved cabin information and any directory entries confirmed for that deck. Published venue deck numbers are included where checked. Your own saved deck assignments take precedence.</p><label for="deckChoice">Choose deck</label><select id="deckChoice">${DECKS.map(n=>`<option value="${n}" ${String(data.deck)===String(n)?'selected':''}>Deck ${n}</option>`).join('')}</select><div class="actions"><button id="showVenueDeck" type="button" aria-expanded="false">Show venue deck information</button></div><div id="venueDeckPanel" hidden></div><div id="deckResults"></div><div id="visualDeck"></div><label for="deckNote">My notes for this deck</label><textarea id="deckNote" placeholder="Add lift locations, facilities or directions you have personally checked"></textarea><div class="actions"><button id="saveDeckNote">Save deck notes</button></div>${shipDiagram()}</section>`}
if(page==='venues'||page==='entertainment'){let filtered=venues.filter(v=>page==='entertainment'?v.category.includes('Entertainment'):v.category.includes('Bar')||v.category.includes('Dining'));h=`<section class="card"><h2>${page==='venues'?'Bars & Restaurants':'Entertainment & Activities'}</h2><p class="muted">Offline venue directory with published deck locations where available. Hours, reservations and showtimes can change.</p>${page==='venues'?'<input id="searchVenue" placeholder="Search venues..." aria-label="Search venues">':''}<label for="venueFilter">Filter directory</label><select id="venueFilter"><option>All</option>${page==='entertainment'?'<option>Entertainment</option>':'<option>Bar</option><option>Dining</option>'}<option>Favourites</option></select><div id="venueList">${venueRows(filtered)}</div><section class="venue-editor"><h3>My venue notes & deck assignments</h3><p class="muted">Personal deck overrides and directions are stored only on your device.</p><label for="venueNoteName">Select venue</label><select id="venueNoteName">${venues.map(v=>`<option value="${esc(v.name)}">${esc(v.name)}</option>`).join('')}</select><label for="venueDeck">Deck (optional, personally verified)</label><select id="venueDeck"><option value="">Unknown / not entered</option>${DECKS.map(d=>`<option value="${d}">Deck ${d}</option>`).join('')}</select><label for="venueNoteText">Personal directions, opening times or booking notes</label><textarea id="venueNoteText"></textarea><div class="actions"><button id="saveVenueNote">Save venue note</button></div></section><p class="muted">Tap ☆ to save favourite venues for quick reference.</p><h3>My favourites</h3><div id="favoriteList">${venueRows(venues.filter(v=>data.favorites.includes(v.name)))}</div></section>${ad(page==='venues'?'venues':'entertainment')}`}
if(page==='drinks'){let period=drinkPeriod(new Date()),passenger=data.activePassenger,tod=data.drinks.filter(x=>periodForDrink(x)===period&&(x.passenger||'Passenger 1')===passenger),used=tod.filter(x=>x.kind==='alcohol').reduce((sum,x)=>sum+x.qty,0),total=tod.reduce((sum,x)=>sum+x.price*x.qty,0);h=`<section class="card"><h2>Drinks allowance tracker</h2><p class="muted">Personal records only. The app uses a 6 am–5:59 am tracking day for newly recorded drinks. Package eligibility, drink limits and charges must be checked against your current P&O package terms. Older V1 drinks retain their original calendar-day grouping.</p><label for="passenger">Passenger</label><select id="passenger">${data.passengers.map(n=>`<option ${n===passenger?'selected':''}>${esc(n)}</option>`).join('')}</select><div class="num">${used} / ${data.limit}</div><p><strong>${Math.max(0,data.limit-used)} remaining</strong> in this personal tracking period</p><div class="meter"><div style="width:${Math.min(100,used/Math.max(1,data.limit)*100)}%"></div></div><p>${Math.max(0,data.limit-used)} remaining in your personal target · Recorded cost ${money(total)}</p><p><small>Tracking period: ${esc(period)} 6 am to next day 5:59 am</small></p>${field('Personal alcoholic drinks target','drinkLimit',data.limit,'number')}<div class="actions"><button id="saveLimit">Save target</button></div><h3>Add another passenger</h3>${field('Passenger name','passengerName')}<div class="actions"><button id="addPassenger">Add passenger</button></div></section><section class="card"><h2>Record a drink</h2>${field('Drink / description','drinkName')}<label for="drinkKind">Type</label><select id="drinkKind"><option value="alcohol">Alcoholic</option><option value="nonalcohol">Non-alcoholic</option></select>${field('Quantity','drinkQty',1,'number')}${field('Cost per drink (£, enter 0 if included)','drinkPrice',0,'number')}<div class="actions"><button id="addDrink">Record now</button></div></section><section class="card"><h2>Current period history</h2>${tod.length?tod.map(x=>`<div class="item row"><span>${esc(x.name)} × ${x.qty}<br><small>${esc(x.kind)} · ${money(x.price*x.qty)}</small></span><button class="danger" data-del-drink="${esc(x.id)}">Delete</button></div>`).join(''):'No drinks recorded in this period.'}</section>`}
if(page==='planner'){h=`<section class="card"><h2>My cruise details</h2>${field('Embarkation date','departure',data.departure,'date')}${field('Cruise length (days)','days',data.days,'number')}<label for="ports">Ports of call / excursions</label><textarea id="ports">${esc(data.ports)}</textarea><div class="actions"><button id="saveCruise">Save cruise details</button></div></section><section class="card"><h2>My daily plans</h2><p class="muted">Activities are sorted by date and time. Times are entered manually; the app does not send notifications.</p><label for="planDayFilter">Show activities for</label><select id="planDayFilter"><option value="all">All days</option>${[...new Set(data.plans.map(x=>x.date).filter(Boolean))].sort().map(d=>`<option value="${esc(d)}">${esc(d)}</option>`).join('')}</select><p class="muted">Select a day to focus on its activities. Use Edit to correct a saved entry.</p>${field('Activity / reservation','planName')}${field('Date','planDate',data.departure||today(),'date')}${field('Time','planTime','19:00','time')}<div class="actions"><button id="addPlan">Add to planner</button><button class="secondary" id="exportPlans">Print / Save plans PDF</button></div><p class="muted">Print or save a PDF copy of your plans. Saved plans remain available offline.</p>${[...data.plans].sort((a,b)=>(a.date+' '+a.time).localeCompare(b.date+' '+b.time)).map(x=>`<div class="item row" data-plan-date="${esc(x.date)}"><span><b>${esc(x.name)}</b><br><small>${esc(x.date)} · ${esc(x.time)}</small></span><span><button class="secondary" data-edit-plan="${esc(x.id)}">Edit</button> <button class="danger" data-del-plan="${esc(x.id)}">Delete</button></span></div>`).join('')}</section>`}
if(page==='planner'){const calls=Array.isArray(data.portCalls)?data.portCalls:[];h+=`<section class="card"><h2>Port day organiser</h2><p class="muted">Keep excursion details and your own return-to-ship reminder together. Always check the ship's official all-aboard time; this app does not provide live schedules or notifications.</p>${field('Port / destination','portName')}${field('Date','portDate',data.departure||today(),'date')}${field('Meeting time (optional)','portMeet','','time')}${field('My return reminder (optional)','portReturn','','time')}<label for="portNotes">Excursion / meeting point notes</label><textarea id="portNotes"></textarea><div class="actions"><button id="addPort">Save port day</button><button class="secondary" id="exportPorts">Print / Save port days PDF</button></div>${calls.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(x=>`<div class="item row"><span><b>${esc(x.name)}</b><br><small>${esc(x.date)} · Meet ${esc(x.meet||'not set')} · Return reminder ${esc(x.returnTime||'not set')}</small><p>${esc(x.notes||'')}</p></span><span><button class="secondary" data-edit-port="${esc(x.id)}">Edit</button> <button class="danger" data-del-port="${esc(x.id)}">Delete</button></span></div>`).join('')}</section>`}
if(page==='packing'){h=packingPage()}
if(page==='spend'){let total=data.spend.reduce((s,x)=>s+x.amount,0);h=`<section class="card"><h2>Holiday spending</h2><div class="num">${money(total)}</div><p class="muted">Manually recorded expenses only; not linked to your onboard account.</p>${field('Purchase / description','spendName')}<label for="spendCategory">Category</label><select id="spendCategory"><option>Shopping</option><option>Drinks</option><option>Dining</option><option>Excursion</option><option>Other</option></select>${field('Amount (£)','spendAmount','','number')}<div class="actions"><button id="addSpend">Add expense</button><button class="secondary" id="exportSpend">Print / Save spending PDF</button></div>${data.spend.map(x=>`<div class="item row"><span>${esc(x.name)} <small>(${esc(x.category)})</small></span><span>${money(x.amount)} <button class="danger" data-del-spend="${esc(x.id)}">×</button></span></div>`).join('')}</section>`}
if(page==='share'){h=`<section class="card"><h2>Share Arvia Cruise Companion</h2><p>Share this app after publishing it to GitHub Pages. The Share and Copy Link buttons use the actual address where the app is opened.</p><p><a href="https://elevor360.github.io/Elevor360D-Arvia-Cruise-Companion/" target="_blank" rel="noopener noreferrer">https://elevor360.github.io/Elevor360D-Arvia-Cruise-Companion/</a></p><p><img src="share-qr.png" alt="QR code to open Arvia Cruise Companion" style="width:220px;max-width:100%;height:auto;background:white;padding:10px;border-radius:12px"></p><p class="muted">Scan this QR code to open the public app. An internet connection is required for first installation.</p><div class="actions"><button id="shareApp" type="button">Share App Link</button><button id="copyAppLink" class="secondary" type="button">Copy App Link</button></div><p id="shareStatus" role="status" aria-live="polite"></p><p class="muted">Only the public app link is shared. Your saved cabin details, plans and other personal information are not included.</p></section>`}
if(page==='settings'){h=`<section class="card"><h2>Backup and restore</h2><p>Personal records stay in this browser on this device. Export a backup before clearing browser data or changing phones.</p><div class="actions"><button id="backup">Download backup JSON</button><label style="margin:0"><span class="tag">Restore JSON backup</span><input type="file" id="restore" accept=".json,application/json" style="max-width:260px"></label></div></section><section class="card"><h2>App information</h2><p>Arvia V1 · Offline PWA · Unofficial independent guide</p><p>Advertising is controlled by the site owner through advert-settings.json. Passenger information is never sent to the advertising manager.</p><button id="reset" class="danger">Erase all personal data</button></section><section class="card"><h2>App readiness check</h2><p class="muted">Check whether this device can save personal data, use offline files and reach published updates. This does not change your saved records.</p><button id="runDiagnostics" type="button">Run checks</button><div id="diagnosticsResult" role="status" aria-live="polite"><p>Press Run checks to begin.</p></div></section>`}
$('#content').innerHTML=h;bind();document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()})}
function venueRows(a){return a.map(v=>`<div class="item"><div class="row"><b>${esc(v.name)}</b><span><button class="secondary" data-fav="${esc(v.name)}" aria-label="Toggle favourite for ${esc(v.name)}">${data.favorites.includes(v.name)?'★':'☆'}</button> <span class="tag">${esc(v.category)}</span></span></div><p>${esc(v.description)}</p><small>Deck: ${esc(venueDeck(v))}</small>${data.venueNotes?.[v.name]?`<p class="muted"><b>My notes:</b> ${esc(data.venueNotes[v.name])}</p>`:''}</div>`).join('')||'<p>No matching venues.</p>'}function id(){return Date.now().toString(36)+Math.random().toString(36).slice(2,7)}function val(k){return $('#'+k)?.value?.trim()||''}function bind(){if(page==='share'){
 const url=new URL('./',location.href).href;
 const status=$('#shareStatus');
 const copy=async()=>{try{await navigator.clipboard.writeText(url);status.textContent='App link copied.'}catch(e){window.prompt('Copy this app link:',url);status.textContent='Copy the link shown above.'}};
 const copyButton=$('#copyAppLink');if(copyButton)copyButton.onclick=copy;
 const shareButton=$('#shareApp');if(shareButton)shareButton.onclick=async()=>{if(navigator.share){try{await navigator.share({title:'Elevor360D Arvia Cruise Companion',text:'Free Arvia Cruise Companion app',url})}catch(e){if(e.name!=='AbortError')await copy()}}else await copy()};
}
if(page==='myday'){
 const date=$('#myDayDate');if(date)date.onchange=()=>{data.myDayDate=date.value;save();render()};
 const todayButton=$('#myDayToday');if(todayButton)todayButton.onclick=()=>{data.myDayDate=today();save();render()};
 const printButton=$('#printMyDay');if(printButton)printButton.onclick=()=>window.print();
 const plannerButton=$('#myDayPlanner');if(plannerButton)plannerButton.onclick=()=>{page='planner';render()};
 const cabinButton=$('#myDayCabin');if(cabinButton)cabinButton.onclick=()=>{page='ship';render()};
}
if(page==='planner'){const add=$('#addPort');if(add)add.onclick=()=>{const name=val('portName'),date=val('portDate');if(!name||!date)return alert('Enter a port and date.');data.portCalls=Array.isArray(data.portCalls)?data.portCalls:[];data.portCalls.push({id:id(),name,date,meet:val('portMeet'),returnTime:val('portReturn'),notes:val('portNotes')});save();render()};const exportPorts=$('#exportPorts');if(exportPorts)exportPorts.onclick=()=>printReport('Port Day Organiser',['Port','Date','Meeting time','Personal return reminder','Notes'],(data.portCalls||[]).slice().sort((a,b)=>a.date.localeCompare(b.date)).map(x=>[x.name,x.date,x.meet,x.returnTime,x.notes]),'Personal reminders only. Check the official all-aboard time onboard.');document.querySelectorAll('[data-edit-port]').forEach(el=>el.onclick=()=>{const x=(data.portCalls||[]).find(p=>p.id===el.dataset.editPort);if(!x)return;const name=prompt('Port / destination',x.name);if(name===null)return;if(!name.trim())return alert('Enter a port name.');const date=prompt('Date (YYYY-MM-DD)',x.date);if(date===null)return;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(Date.parse(date)))return alert('Enter a valid date.');const meet=prompt('Meeting time (HH:MM or blank)',x.meet||'');if(meet===null)return;const ret=prompt('Personal return reminder (HH:MM or blank)',x.returnTime||'');if(ret===null)return;for(const t of [meet,ret])if(t&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(t))return alert('Use 24-hour time HH:MM or leave blank.');const notes=prompt('Excursion notes',x.notes||'');if(notes===null)return;Object.assign(x,{name:name.trim(),date,meet,returnTime:ret,notes});save();render()});document.querySelectorAll('[data-del-port]').forEach(el=>el.onclick=()=>{if(!confirm('Delete this port day?'))return;data.portCalls=(data.portCalls||[]).filter(x=>x.id!==el.dataset.delPort);save();render()})}if(page==='packing'){document.querySelectorAll('[data-pack-check]').forEach(el=>el.onchange=()=>{let item=data.packing.find(x=>x.id===el.dataset.packCheck);if(item){item.done=el.checked;save();render()}});document.querySelectorAll('[data-pack-remove]').forEach(el=>el.onclick=()=>{data.packing=data.packing.filter(x=>x.id!==el.dataset.packRemove);save();render()});$('#addPacking').onclick=()=>{let name=val('packingName');if(!name)return alert('Enter an item.');data.packing.push({id:id(),name,category:val('packingCategory'),done:false});save();render()};$('#resetPacking').onclick=()=>{if(confirm('Untick all packing items?')){data.packing.forEach(x=>x.done=false);save();render()}};$('#exportPacking').onclick=()=>printReport('Holiday Packing Checklist',['Category','Item','Packed'],data.packing.map(x=>[x.category,x.name,x.done?'Yes':'No']));}if(page==='facilities'){facilityRows();$('#facilitySearch').oninput=facilityRows;$('#facilityCategory').onchange=facilityRows}if(page==='cabins'){
let results=$('#cabinResults'),search=$('#cabinSearch');const show=()=>{results.innerHTML=cabinRows(search.value);document.querySelectorAll('[data-remove-cabin]').forEach(el=>el.onclick=()=>{if(confirm('Delete cabin '+el.dataset.removeCabin+'?')){data.cabinDirectory=data.cabinDirectory.filter(x=>x.cabin!==el.dataset.removeCabin);save();show()}})};search.oninput=show;show();
$('#addCabinEntry').onclick=()=>{let cabin=val('entryCabin').toUpperCase(),deck=val('entryDeck');if(!/^[A-Z0-9-]{2,12}$/.test(cabin)||!/^\d{1,2}$/.test(deck)||Number(deck)<3||Number(deck)>18)return alert('Enter a cabin number and a deck between 3 and 18.');let entry={cabin,deck,zone:val('entryZone'),side:val('entrySide'),type:val('entryType'),notes:val('entryNotes')};data.cabinDirectory=(data.cabinDirectory||[]).filter(x=>x.cabin!==cabin);data.cabinDirectory.push(entry);save();render()};
$('#exportCabins').onclick=()=>printReport('My Cabin Directory',['Cabin','Deck','Section','Side','Type','Notes'],(data.cabinDirectory||[]).map(x=>[x.cabin,x.deck,x.zone,x.side,x.type,x.notes]),'Passenger-maintained entries; not an official numbered cabin plan.');
$('#importCabins').onchange=async e=>{try{let rows=parseCSV(await e.target.files[0].text());let headers=rows.shift().map(x=>x.trim().toLowerCase());let required=['cabin','deck','zone','side','type','notes'];if(required.some(x=>!headers.includes(x)))throw Error('CSV needs cabin,deck,zone,side,type,notes columns.');let valid=[];for(let row of rows){if(row.every(x=>!x.trim()))continue;let o=Object.fromEntries(required.map(k=>[k,(row[headers.indexOf(k)]||'').trim()]));o.cabin=o.cabin.toUpperCase();if(!/^[A-Z0-9-]{2,12}$/.test(o.cabin)||!/^\d{1,2}$/.test(o.deck)||Number(o.deck)<3||Number(o.deck)>18)throw Error('Invalid cabin/deck in CSV: '+o.cabin);valid.push(o)}if(valid.length>3000)throw Error('Maximum 3000 records per import');if(!confirm('Import '+valid.length+' cabin records?'))return;let map=new Map((data.cabinDirectory||[]).map(x=>[x.cabin,x]));valid.forEach(x=>map.set(x.cabin,x));data.cabinDirectory=[...map.values()];save();render()}catch(err){alert(err.message)}};
}let zone=$('#saveCabinZone');if(zone)zone.onclick=()=>{data.cabinZone=val('cabinZone');save();alert('Cabin section saved')};let deck=$('#deckChoice');if(deck){let update=()=>{let d=deck.value;$('#visualDeck').innerHTML=visualDeck(d);$('#deckResults').innerHTML=`<div class="item"><b>Deck ${esc(d)}</b><p>${String(data.deck)===d&&data.cabin?'Your saved cabin: '+esc(data.cabin):'No personal cabin saved for this deck.'}</p></div>`;const panel=$('#venueDeckPanel');const matching=venues.filter(v=>String(venueDeck(v)).split(/[^0-9]+/).includes(d));const facilities=FACILITIES.filter(f=>String(f.deck).split(/[^0-9]+/).includes(d));panel.innerHTML=`<section class="card"><h3>Venue deck information · Deck ${esc(d)}</h3><p class="muted">Published venue assignments and your personal overrides. Multi-deck locations may be approximate.</p><h4>Bars, dining & entertainment (${matching.length})</h4>${venueRows(matching)}<h4>Facilities (${facilities.length})</h4>${facilities.map(f=>`<div class="item"><b>${esc(f.name)}</b><p>${esc(f.notes)}</p></div>`).join('')||'<p>No individually mapped facilities on this deck.</p>'}</section>`;$('#deckNote').value=data.deckNotes?.[d]||''};deck.onchange=update;update();$('#showVenueDeck').onclick=()=>{let panel=$('#venueDeckPanel');panel.hidden=!panel.hidden;$('#showVenueDeck').textContent=panel.hidden?'Show venue deck information':'Hide venue deck information';$('#showVenueDeck').setAttribute('aria-expanded',String(!panel.hidden))};$('#saveDeckNote').onclick=()=>{data.deckNotes=data.deckNotes||{};data.deckNotes[deck.value]=val('deckNote');save();alert('Deck notes saved')}}
let venueName=$('#venueNoteName');if(venueName){let updateNote=()=>{$('#venueNoteText').value=data.venueNotes?.[venueName.value]||'';$('#venueDeck').value=data.venueDecks?.[venueName.value]||''};venueName.onchange=updateNote;updateNote();$('#saveVenueNote').onclick=()=>{data.venueNotes=data.venueNotes||{};data.venueNotes[venueName.value]=val('venueNoteText');data.venueDecks=data.venueDecks||{};if(val('venueDeck'))data.venueDecks[venueName.value]=val('venueDeck');else delete data.venueDecks[venueName.value];save();render();alert('Venue note saved')}}
let filter=$('#venueFilter'),searchBox=$('#searchVenue');if(filter){filter.value=[...filter.options].some(o=>o.value===(data.venueFilter||'All'))?data.venueFilter:'All';let apply=()=>{data.venueFilter=filter.value;save();let filtered=venues.filter(v=>(page==='entertainment'?v.category.includes('Entertainment'):v.category.includes('Bar')||v.category.includes('Dining'))&&(filter.value==='All'||(filter.value==='Favourites'?data.favorites.includes(v.name):v.category.includes(filter.value)))&&(v.name+' '+v.description+' '+(data.venueNotes?.[v.name]||'')).toLowerCase().includes((searchBox?.value||'').toLowerCase()));$('#venueList').innerHTML=venueRows(filtered);bindFavorites()};filter.onchange=apply;if(searchBox)searchBox.oninput=apply;apply()}
let diagnosticButton=$('#runDiagnostics');if(diagnosticButton)diagnosticButton.onclick=async()=>{
 const out=$('#diagnosticsResult');out.textContent='Checking…';const lines=[];
 try{const k='arvia-test-storage';localStorage.setItem(k,'ok');const ok=localStorage.getItem(k)==='ok';localStorage.removeItem(k);lines.push([ok,'Personal data storage',ok?'Working':'Not available']);}catch(e){lines.push([false,'Personal data storage','Not available']);}
 lines.push([navigator.onLine,'Network connection',navigator.onLine?'Online':'Offline (normal at sea)']);
 lines.push([Boolean(navigator.serviceWorker?.controller),'Offline app controller',navigator.serviceWorker?.controller?'Active':'Not active yet — reload after installing']);
 if('caches' in window){try{const keys=await caches.keys();lines.push([keys.some(k=>k.startsWith('elevor360d-arvia-static-v1-1')),'Arvia V1.1 offline cache',keys.some(k=>k.startsWith('elevor360d-arvia-static-v1-1'))?'Present':'Not ready — reload online']);}catch{lines.push([false,'Offline cache','Unable to inspect']);}}
 for(const [label,file] of [['Venue directory','venues.json'],['Passenger information','information.json'],['Advertisement settings','advert-settings.json']]){
  try{const response=await fetch('./'+file+'?readiness='+Date.now(),{cache:'no-store'});if(!response.ok)throw Error('HTTP '+response.status);await response.json();lines.push([true,label,'Available']);}catch{lines.push([false,label,'Unavailable right now (may work from saved cache)']);}
 }
 out.innerHTML='<ul>'+lines.map(([ok,label,status])=>'<li><b>'+esc(label)+':</b> '+esc(status)+'</li>').join('')+'</ul><p class="muted">A successful check does not guarantee all features work. Test printing, backup/restore and offline reopening before release.</p>';
};
let infoSearch=$('#infoSearch');if(infoSearch){const filterInfo=()=>{const q=infoSearch.value.trim().toLowerCase();let shown=0;document.querySelectorAll('.info-section').forEach(el=>{const match=el.dataset.search.includes(q);el.hidden=!match;if(match)shown++});$('#infoCount').textContent=shown+' of '+document.querySelectorAll('.info-section').length+' information sections shown';};infoSearch.oninput=filterInfo;filterInfo();}
let refreshButton=$('#refreshInfo');if(refreshButton)refreshButton.onclick=async()=>{updateStatus='Checking for updates…';$('#updateStatus').textContent=updateStatus;try{const response=await fetch('./information.json?v=arvia1&check='+Date.now(),{cache:'no-store'});if(!response.ok)throw Error('HTTP '+response.status);const incoming=await response.json();if(!incoming||!Array.isArray(incoming.sections))throw Error('Invalid information file');information=incoming;localStorage.setItem('arvia_public_information_cache',JSON.stringify(incoming));updateStatus='Information checked successfully. Last checked: '+new Date().toLocaleString('en-GB');localStorage.setItem('arvia_information_last_check',updateStatus);render()}catch(e){updateStatus='Unable to check online. Showing the last saved information, if available.';$('#updateStatus').textContent=updateStatus}};function bindFavorites(){document.querySelectorAll('[data-fav]').forEach(el=>el.onclick=()=>{let name=el.dataset.fav;data.favorites=data.favorites.includes(name)?data.favorites.filter(x=>x!==name):[...data.favorites,name];save();render()})}bindFavorites();let passenger=$('#passenger');if(passenger)passenger.onchange=()=>{data.activePassenger=passenger.value;save();render()};let b=(k,f)=>{let e=$('#'+k);if(e)e.onclick=f};b('saveCabin',()=>{Object.assign(data,{cabin:val('cabin'),deck:val('deck'),muster:val('muster'),notes:val('notes'),cabinRoute:val('cabinRoute')});save();render()});b('saveCruise',()=>{Object.assign(data,{departure:val('departure'),days:Number(val('days'))||7,ports:val('ports')});save();render()});b('addPassenger',()=>{let name=val('passengerName');if(!name||name.length>50||data.passengers.includes(name))return alert('Enter a unique passenger name (up to 50 characters).');data.passengers.push(name);data.activePassenger=name;save();render()});b('saveLimit',()=>{data.limit=Math.max(1,Number(val('drinkLimit'))||15);save();render()});b('addDrink',()=>{let name=val('drinkName'),qty=Number(val('drinkQty')),price=Number(val('drinkPrice'));if(!name||!Number.isInteger(qty)||qty<1||qty>100||!Number.isFinite(price)||price<0)return alert('Enter a name, valid quantity and cost.');if(val('drinkKind')==='alcohol'){let period=drinkPeriod(new Date());let current=data.drinks.filter(x=>periodForDrink(x)===period&&(x.passenger||'Passenger 1')===data.activePassenger&&x.kind==='alcohol').reduce((n,x)=>n+Number(x.qty||0),0);if(current+qty>data.limit&&!confirm('This entry exceeds your manually set daily limit. Record it anyway?'))return;}data.drinks.push({id:id(),name,kind:val('drinkKind'),qty,price,date:today(),period:drinkPeriod(new Date()),passenger:data.activePassenger});save();render()});let dayFilter=$('#planDayFilter');if(dayFilter){const applyDay=()=>document.querySelectorAll('[data-plan-date]').forEach(el=>{el.hidden=dayFilter.value!=='all'&&el.dataset.planDate!==dayFilter.value});dayFilter.onchange=applyDay;applyDay();document.querySelectorAll('[data-edit-plan]').forEach(el=>el.onclick=()=>{const plan=data.plans.find(x=>String(x.id)===el.dataset.editPlan);if(!plan)return;const name=prompt('Activity or reservation',plan.name);if(name===null)return;if(!name.trim())return alert('Activity cannot be empty.');const date=prompt('Date (YYYY-MM-DD)',plan.date);if(date===null)return;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(Date.parse(date)))return alert('Enter a valid date YYYY-MM-DD.');const time=prompt('Time (HH:MM, 24-hour)',plan.time);if(time===null)return;if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(time))return alert('Enter a valid 24-hour time.');plan.name=name.trim();plan.date=date;plan.time=time;save();render()})};b('exportPlans',()=>printReport('My Daily Plans',['Activity','Date','Time'],(data.plans||[]).slice().sort((a,b)=>(a.date+' '+a.time).localeCompare(b.date+' '+b.time)).map(x=>[x.name,x.date,x.time])));b('addPlan',()=>{if(!val('planName'))return alert('Enter an activity.');data.plans.push({id:id(),name:val('planName'),date:val('planDate'),time:val('planTime')});save();render()});b('exportSpend',()=>{const rows=(data.spend||[]).map(x=>[x.name,x.category,'£'+Number(x.amount||0).toFixed(2)]);rows.push(['TOTAL','','£'+data.spend.reduce((sum,x)=>sum+Number(x.amount||0),0).toFixed(2)]);printReport('Holiday Spending',['Description','Category','Amount'],rows)});b('addSpend',()=>{let n=val('spendName'),amount=Number(val('spendAmount'));if(!n||!Number.isFinite(amount)||amount<=0)return alert('Enter an expense and positive amount.');data.spend.push({id:id(),name:n,category:val('spendCategory'),amount});save();render()});for(let type of ['drink','plan','spend'])document.querySelectorAll(`[data-del-${type}]`).forEach(el=>el.onclick=()=>{data[type==='drink'?'drinks':type==='plan'?'plans':'spend']=data[type==='drink'?'drinks':type==='plan'?'plans':'spend'].filter(x=>x.id!==el.getAttribute('data-del-'+type));save();render()});b('backup',()=>{let blob=new Blob([JSON.stringify({app:'elevor-arvia',version:"1",data},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='arvia-cruise-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});let restore=$('#restore');if(restore)restore.onchange=async()=>{try{let obj=JSON.parse(await restore.files[0].text());if(obj.app!=='elevor-arvia'||!obj.data||!Array.isArray(obj.data.drinks)||!Array.isArray(obj.data.plans)||!Array.isArray(obj.data.spend))throw Error('Not a valid Arvia backup');if(!confirm('Replace your current saved data with this backup?'))return;data={...data,...obj.data};if(!Array.isArray(data.passengers)||!data.passengers.length)data.passengers=['Passenger 1'];if(!data.passengers.includes(data.activePassenger))data.activePassenger=data.passengers[0];if(!Array.isArray(data.packing))data.packing=PACKING_DEFAULTS.map(([category,name],i)=>({id:'default-'+i,category,name,done:false}));save();render();alert('Backup restored')}catch(e){alert(e.message)}};b('reset',()=>{if(confirm('Permanently erase all personal records on this device?')){localStorage.removeItem(KEY);localStorage.removeItem(V12KEY);localStorage.removeItem(V11KEY);localStorage.removeItem(V10KEY);localStorage.removeItem(V9KEY);localStorage.removeItem(V8KEY);localStorage.removeItem(V7KEY);localStorage.removeItem(V6KEY);localStorage.removeItem(V5KEY);localStorage.removeItem(V43KEY);localStorage.removeItem(V42KEY);localStorage.removeItem(PREVKEY);localStorage.removeItem(V4KEY);localStorage.removeItem(V3KEY);localStorage.removeItem(OLDKEY);localStorage.removeItem(LEGACYKEY);location.reload()}})}
async function init(){try{venues=await(await fetch('./venues.json')).json()}catch{venues=[]}try{ads=await(await fetch('./advert-settings.json',{cache:'no-store'})).json()}catch{}try{let cached=localStorage.getItem('arvia_public_information_cache');if(cached){let saved=JSON.parse(cached);if(Array.isArray(saved.sections))information=saved}let response=await fetch('./information.json?v=arvia1',{cache:'no-store'});if(response.ok){let incoming=await response.json();if(incoming&&Array.isArray(incoming.sections)){information=incoming;localStorage.setItem('arvia_public_information_cache',JSON.stringify(incoming))}}}catch{}render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}let deferred;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e;$('#install').hidden=false});$('#install').onclick=async()=>{if(!deferred)return;deferred.prompt();await deferred.userChoice;deferred=null;$('#install').hidden=true};window.addEventListener('appinstalled',()=>{$('#install').hidden=true});init();